const landing=document.querySelector('main').outerHTML, header=document.querySelector('header').outerHTML, footer=document.querySelector('footer').outerHTML;
const brand='<a class="brand" href="#/"><span>S</span>StudyLink</a>';
let profile={name:'Tomi Adeyemi',email:'tomi@example.com',role:'Student'}, timer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(s){const t=document.querySelector('.toast');t.textContent=s;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),4500);}
const sessions=[['08','Data structures: trees & graphs','Amina Okafor','Tuesday, 8 September · 4:00–5:00 PM WAT','CSC 201'],['10','Integration techniques','Khadijah Ahmed','Thursday, 10 September · 2:00–3:00 PM WAT','MTH 201']];
const materials=[['CSC 201','Trees & graphs, simplified','Study guide · Added 7 Sep','A tree is a connected graph without cycles.\nPractice: Draw a binary search tree for 8, 3, 10, 1, 6.\nSolution: Root 8; children 3 and 10; children of 3 are 1 and 6.\nBreadth-first traversal: 8, 3, 10, 1, 6.'],['MTH 201','Past questions & worked solutions','Past questions · 2024/25','Original demo practice, not an official exam.\n1. Integrate 2x + 3.\nSolution: x² + 3x + C.\n2. Differentiate sin(x²).\nSolution: 2x cos(x²).'],['STA 201','Probability essentials','Lecture handout · Added 5 Sep','Independent events: P(A and B) = P(A) × P(B).\nTwo fair coin flips both landing heads: probability 1/4.\nProbability of at least one head: 1 - 1/4 = 3/4.']];
function field(id,label,type='text',auto='',extra=''){return `<label class="field" for="${id}">${label}<span class="input-wrap"><input id="${id}" name="${id}" type="${type}" autocomplete="${auto}" required ${extra}>${type==='password'?`<button type="button" class="reveal" data-reveal="${id}" aria-label="Show ${label.toLowerCase()}" aria-pressed="false">Show</button>`:''}</span></label>`;}
function auth(mode){const signup=mode==='signup',forgot=mode==='forgot';return `<header class="auth-nav">${brand}<a href="#/">← Back to home</a></header><main id="main-content" class="auth-layout"><aside class="auth-story"><span class="kicker">YOUR NEXT CHAPTER</span><h1>A little support.<br>A lot of<br><em>possibility.</em></h1><p>Your people, your study materials, and a clearer path through the semester.</p><div class="auth-quote"><span class="quote-mark">“</span><blockquote>Having someone break down the difficult topics made all the difference. I finally feel ready for my exams.</blockquote><div class="person"><span class="avatar">TO</span><div><b>Temi O.</b><small>Engineering student · Demo story</small></div></div></div><div class="auth-bottom">PEER SUPPORT. REAL PROGRESS.</div></aside><section class="auth-form"><div class="form-inner"><span class="kicker">${forgot?'LET’S GET YOU BACK IN':signup?'START SOMETHING GOOD':'GOOD TO SEE YOU AGAIN'}</span><h2>${forgot?'Forgot your password?':signup?'Make room for progress.':'Welcome back.'}</h2><p class="subtle">${forgot?'Enter your email to preview the reset flow.':signup?'Join a community that learns better, together.':'Your next breakthrough is waiting for you.'}</p><div class="demo-note">Demo experience · Use sample details. No real account is created and passwords are never saved.</div><form id="auth-form" data-mode="${mode}">${signup?field('full-name','Full name','text','name','maxlength="80"'):''}${field('email','Email address','email','email','placeholder="you@example.com"')}${!forgot?field('password','Password','password',signup?'new-password':'current-password','minlength="8" maxlength="128" aria-describedby="password-hint"')+'<small id="password-hint" class="hint">Use at least 8 characters for this demo.</small>':''}${signup?field('confirm-password','Confirm password','password','new-password','minlength="8"')+`<fieldset class="role-picker"><legend>I’m joining as a</legend><label><input type="radio" name="role" value="Student" checked> Student</label><label><input type="radio" name="role" value="Tutor"> Tutor</label></fieldset><label class="check"><input type="checkbox" required><span>I agree to the <button type="button" class="inline-link" data-info="terms">demo terms</button> and understand this is a preview.</span></label>`:!forgot?'<div class="form-options"><label class="check"><input type="checkbox" id="remember"> Remember my email</label><a href="#/forgot">Forgot password?</a></div>':''}<p id="form-error" class="form-error" role="alert"></p><button class="primary full">${forgot?'Preview reset instructions':signup?'Create demo account':'Log in to demo'} <span>→</span></button></form><p class="auth-switch">${forgot?'<a href="#/login">← Return to login</a>':signup?'Already part of StudyLink? <a href="#/login">Log in</a>':'New around here? <a href="#/signup">Create an account</a>'}</p>${!forgot?'<a class="demo-link" href="#/dashboard">Just exploring? View the student dashboard →</a>':''}</div></section></main>`;}
function sessionRows(){return sessions.map((s,i)=>`<article class="session-row"><div class="date-tile"><b>${s[0]}</b><small>SEP</small></div><div class="row-body"><span class="course-code">${s[4]}</span><h3>${s[1]}</h3><p>${s[2]} · Online</p><small>${s[3]}</small></div><button class="secondary" data-session="${i}">Details ↗</button></article>`).join('');}
function materialRows(){return materials.map((m,i)=>`<article class="material-row"><span class="file-icon">TXT</span><div class="row-body"><span class="course-code">${m[0]}</span><h3>${m[1]}</h3><p>${m[2]}</p></div><button class="icon-btn" data-material="${i}" aria-label="Download ${m[1]}">↓</button></article>`).join('');}
function plan(){return `<section class="panel plan-card"><div class="panel-head"><span class="kicker">YOUR SUBSCRIPTION</span><span class="status">● Active</span></div><h2>Scholar <span>plan</span></h2><p>A little extra support for your semester.</p><div class="plan-amount">₦4,500 <small>/ month</small></div><div class="plan-meta"><span>Next renewal</span><b>1 October 2026</b></div><div class="plan-meta"><span>Sessions remaining</span><b>2 of 2 this month</b></div><a class="secondary full" href="#/dashboard/subscription">View plan details →</a></section>`;}
function tutor(){return `<section class="panel"><div class="panel-head"><h2>Your learning partner</h2><span class="status">Verified</span></div><div class="person tutor-person"><div class="portrait">AO</div><div><h3>Amina Okafor</h3><p>Computer Science · 400 Level</p><b class="tutor-rating">★ 4.9 <span>· 86 sessions</span></b></div></div><div class="tags"><span>Data Structures</span><span>Python</span><span>Algorithms</span></div><p class="subtle">“We’ll build your confidence, one concept at a time.”</p><button class="secondary full" data-info="tutor">View tutor profile →</button></section>`;}
const navItems=[['overview','◫','Dashboard'],['tutors','♧','Tutors'],['materials','▤','Materials'],['sessions','▦','Sessions'],['subscription','◇','Subscription'],['profile','○','Profile']];
function dashboard(view){let content;
if(view==='overview')content=`<section class="welcome-banner"><div><span class="kicker">SMALL STEPS, STEADY PROGRESS</span><h2>You’re building a great semester.</h2><p>Your next session with Amina is tomorrow. Let’s keep the momentum going.</p><a href="#/dashboard/sessions" class="primary">Prepare for your session →</a></div><div class="weekly-goal"><div class="goal-ring"><b>75<small>%</small></b></div><span>Weekly study goal</span><small>6 of 8 hours completed</small></div></section><div class="stats-grid"><article><span>Study hours</span><strong>24.5 <small>hrs</small></strong><p>↑ 4.5 hours this month</p></article><article><span>Sessions completed</span><strong>08</strong><p>Across 3 courses</p></article><article><span>Materials explored</span><strong>16</strong><p>4 added this week</p></article><article><span>Practice average</span><strong>82<small>%</small></strong><p>↑ 12 points this semester</p></article></div><div class="dashboard-columns"><div class="main-column"><section class="panel"><div class="panel-head"><h2>Coming up next</h2><a href="#/dashboard/sessions">All sessions →</a></div>${sessionRows()}</section><section class="panel"><div class="panel-head"><h2>Your study shelf</h2><a href="#/dashboard/materials">Browse materials →</a></div>${materialRows()}</section><section class="panel"><div class="panel-head"><h2>Course progress</h2><span class="subtle">This semester</span></div>${[['Data Structures',78],['Calculus II',65],['Statistics',88]].map(([n,v])=>`<div class="progress-item"><label>${n}<b>${v}%</b></label><progress value="${v}" max="100" aria-label="${n} progress">${v}%</progress></div>`).join('')}</section></div><aside class="main-column">${plan()}${tutor()}<section class="panel quick-actions"><h2>Make your next move</h2><a href="#/dashboard/tutors">Find a tutor <span>↗</span></a><a href="#/dashboard/materials">Practice past questions <span>↗</span></a></section></aside></div>`;
else if(view==='sessions')content=`<section class="panel"><div class="panel-head"><h2>September sessions</h2><span class="status">2 scheduled</span></div><p class="subtle">All times are West Africa Time (UTC+1). These are sample appointments.</p>${sessionRows()}</section>`;
else if(view==='materials')content=`<section class="panel"><div class="panel-head"><h2>Your resource library</h2><span class="status">Scholar access</span></div><p class="subtle">Download short sample handouts and original practice questions as text files.</p>${materialRows()}</section>`;
else if(view==='tutors')content=`<div class="dashboard-columns"><div>${tutor()}</div><section class="panel"><span class="kicker">EXPLORE YOUR OPTIONS</span><h2>Find your next learning partner.</h2><p class="subtle">Browse peer tutors by course and subject on StudyLink.</p><a href="#tutors" class="primary">Browse tutors →</a></section></div>`;
else if(view==='subscription')content=`<div class="dashboard-columns"><div>${plan()}</div><section class="panel"><h2>Your Scholar benefits</h2><ul class="benefits"><li>2 one-to-one tutoring sessions per month</li><li>Full study resource library access</li><li>Course handouts and past questions</li><li>Personal academic progress tracking</li></ul><div class="demo-note">This is a sample subscription. No payment has been taken, and no automatic renewal will occur.</div><a class="secondary" href="#plans">Compare plans →</a></section></div>`;
else content=`<section class="panel profile-panel"><h2>Your profile</h2><p class="subtle">Changes apply to this demo until the page is refreshed.</p><form id="profile-form">${field('profile-name','Full name','text','name','maxlength="80"')}${field('profile-email','Email address','email','email')}<p>Selected role: <b>${esc(profile.role)}</b></p><button class="primary">Save demo profile</button></form></section>`;
const title=navItems.find(x=>x[0]===view)[2];return `<div class="dashboard-shell"><aside class="sidebar">${brand}<span class="sidebar-label">YOUR STUDY SPACE</span><nav aria-label="Dashboard">${navItems.map(([key,icon,label])=>`<a href="#/dashboard${key==='overview'?'':'/'+key}" ${key===view?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="support-note"><b>A little help goes a long way.</b><p>Make time for your next breakthrough.</p><a href="#/dashboard/tutors">Meet your tutor →</a></div><a href="#/" class="home-link">← Visit homepage</a><button class="logout" data-logout>↪ Log out</button></div></aside><div class="dashboard-main"><header class="dashboard-topbar"><span>My campus <span class="separator">/</span> <b>${title}</b></span><div><span class="demo-badge">Demo workspace</span><a class="avatar" href="#/dashboard/profile" aria-label="View profile">${esc(profile.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</a></div></header><main id="main-content" class="dashboard-content"><div class="welcome-header"><div><span class="kicker">MONDAY, 7 SEPTEMBER 2026</span><h1>${view==='overview'?`Welcome back, ${esc(profile.name.split(' ')[0])} <span class="wave">✦</span>`:title}</h1><p>${view==='overview'?'A fresh week. A little more confidence. Let’s make it count.':'Your learning, all in one place.'}</p></div><a class="secondary" href="#/dashboard/materials">Browse materials ↗</a></div>${profile.role==='Tutor'?'<div class="demo-note">You selected Tutor. This preview shows the Student Dashboard; a tutor workspace is not included.</div>':''}${content}</main><footer class="dashboard-footer">StudyLink · Learn better, together.<span>Sample data · September 2026</span></footer></div></div>`;}
function dialog(title,body){const d=document.querySelector('dialog');d.innerHTML=`<div class="panel-head"><h2>${title}</h2><button class="icon-btn" data-close aria-label="Close dialog">×</button></div>${body}<button class="primary full" data-close>Got it</button>`;d.showModal();}
function render(){const route=location.hash.slice(1)||'/',isDash=route.startsWith('/dashboard'),isAuth=['/login','/signup','/forgot'].includes(route);let view=route.split('/')[2]||'overview';if(!navItems.some(x=>x[0]===view))view='overview';document.body.className=isDash?'dashboard-page':isAuth?'auth-page':'';document.body.innerHTML=`<a href="#main-content" class="skip-link">Skip to content</a>${isDash?dashboard(view):isAuth?auth(route.slice(1)):header+landing+footer}<div class="toast" role="status" aria-live="polite"></div><dialog aria-label="StudyLink details"></dialog>`;
if(!isDash&&!isAuth){document.querySelector('main').id='main-content';document.querySelectorAll('.brand').forEach(a=>a.href='#/');document.querySelector('.nav-actions .text-btn').outerHTML='<a class="text-btn" href="#/login">Log in</a>';document.querySelector('.nav-actions .primary').outerHTML='<a class="primary small" href="#/signup">Join StudyLink</a>';document.querySelector('.nav nav').insertAdjacentHTML('beforeend','<a class="mobile-auth" href="#/login">Log in</a><a class="mobile-auth" href="#/signup">Sign up</a>');document.querySelectorAll('.price-grid button,.session button,.card-foot button').forEach(b=>b.onclick=()=>location.hash='/signup');document.querySelector('.white-btn').href='#/signup';const menu=document.querySelector('.menu');menu.setAttribute('aria-expanded','false');menu.onclick=()=>menu.setAttribute('aria-expanded',String(document.querySelector('.nav nav').classList.toggle('open')));const search=()=>{const q=document.querySelector('.search input').value.trim().toLowerCase();let count=0;document.querySelectorAll('.tutor-card').forEach(c=>{c.hidden=!c.textContent.toLowerCase().includes(q);if(!c.hidden)count++;});notify(`${count} tutors found${count?'':'. Try Calculus, Biology, or Accounting.'}`);};document.querySelector('.search button').onclick=search;document.querySelector('.search input').onkeydown=e=>{if(e.key==='Enter')search();};document.querySelectorAll('footer a[href="#"]').forEach(a=>a.onclick=e=>{e.preventDefault();dialog(a.textContent,'<p>StudyLink is a peer tutoring and mentorship demo. No live support or contact service is connected to this preview.</p>');});}
if(isAuth){try{const saved=localStorage.getItem('studylink-demo-email');if(saved&&route==='/login'){document.querySelector('#email').value=saved;document.querySelector('#remember').checked=true;}}catch{}document.querySelector('#auth-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,email=f.elements.email.value.trim(),mode=f.dataset.mode,error=document.querySelector('#form-error');if(mode==='forgot'){dialog('Reset flow preview','<p>A connected service would send a time-limited reset link after this step. This demo has not sent an email.</p><p>Return to login and use a sample email with an 8-character password.</p>');return;}if(mode==='signup'){const name=f.elements['full-name'].value.trim();if(!name){error.textContent='Please enter your full name.';return;}if(f.elements.password.value!==f.elements['confirm-password'].value){error.textContent='Your passwords don’t match. Please try again.';f.elements['confirm-password'].focus();return;}profile={name,email,role:f.elements.role.value};}else{profile={...profile,email};try{if(document.querySelector('#remember').checked)localStorage.setItem('studylink-demo-email',email);else localStorage.removeItem('studylink-demo-email');}catch{}}location.hash='/dashboard';};}
if(isDash&&view==='profile'){document.querySelector('#profile-name').value=profile.name;document.querySelector('#profile-email').value=profile.email;document.querySelector('#profile-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#profile-name').value.trim();if(!name){notify('Please enter your full name.');return;}profile.name=name;profile.email=document.querySelector('#profile-email').value.trim();render();notify('Demo profile saved for this visit.');};}
document.title=`${isDash?'Student Dashboard':isAuth?({'/login':'Log in','/signup':'Sign up','/forgot':'Reset password'}[route]):'Learn better, together'} — StudyLink`;if(!route.startsWith('/'))requestAnimationFrame(()=>document.getElementById(route)?.scrollIntoView());else window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.reveal){const input=document.getElementById(b.dataset.reveal),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',`${show?'Hide':'Show'} ${input.id==='confirm-password'?'confirm password':'password'}`);}if(b.hasAttribute('data-logout')){profile={name:'Tomi Adeyemi',email:'tomi@example.com',role:'Student'};location.hash='/login';}if(b.hasAttribute('data-close'))document.querySelector('dialog').close();if(b.dataset.info==='terms')dialog('Demo terms','<p>This website is an interactive preview. Use sample details. Accounts, subscriptions, sessions, and tutors are examples; no real booking or payment is made.</p><p>Only “Remember my email” saves information on this device. Passwords are never stored or sent.</p>');if(b.dataset.info==='tutor')dialog('Meet Amina Okafor','<p><b>Computer Science · 400 Level</b><br>★ 4.9 from 86 sample sessions</p><p>Amina explains algorithms with practical examples and breaks complex problems into small, manageable steps.</p><p><b>Subjects:</b> Data Structures, Python, Algorithms</p><p><b>Next session:</b> 8 September, 4:00 PM WAT</p><p class="subtle">Demo profile. No real tutor is contacted.</p>');if(b.dataset.session!==undefined){const s=sessions[Number(b.dataset.session)];dialog(s[1],`<p><b>${s[2]}</b> · ${s[4]}</p><p>${s[3]}</p><h3>Before you arrive</h3><p>Bring lecture notes, two questions you want to work through, and a notebook for practice.</p><div class="demo-note">Sample session. No meeting room or live booking is connected.</div>`);}if(b.dataset.material!==undefined){const m=materials[Number(b.dataset.material)],url=URL.createObjectURL(new Blob([`StudyLink — Sample learning resource\n${m[0]}: ${m[1]}\n\n${m[3]}\n`],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=m[1].replace(/[^a-z0-9]+/gi,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Sample learning resource downloaded.');}});
window.addEventListener('hashchange',render);render();
// Keep keyboard skip navigation within the active route.
document.addEventListener('click', event => {
  if (event.target.closest('.skip-link')) {
    event.preventDefault();
    const main = document.querySelector('main');
    main.tabIndex = -1;
    main.focus();
  }
});
window.addEventListener('hashchange', () => {
  if (location.hash.startsWith('#/')) {
    const main = document.querySelector('main');
    main.tabIndex = -1;
    main.focus({preventScroll:true});
  }
});
